<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>롯데월드타워 건축 설계 과정 분석 - ministral-14b</title>
    <style>
        :root {
            --primary: #1a1a2e;
            --secondary: #16213e;
            --accent: #ff9a56;
            --text: #e6e6e6;
            --text-secondary: #a0a0a0;
            --bg: #0a0a1a;
            --highlight: #ffd166;
            --border: #333;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Segoe UI', 'Roboto', 'Noto Sans', sans-serif;
        }

        body {
            background-color: var(--bg);
            color: var(--text);
            line-height: 1.6;
            overflow-x: hidden;
        }

        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px;
        }

        header {
            text-align: center;
            padding: 20px 0;
            border-bottom: 1px solid var(--border);
            margin-bottom: 30px;
        }

        h1 {
            font-size: 2.2rem;
            margin-bottom: 10px;
            color: var(--accent);
        }

        .subtitle {
            font-size: 1.1rem;
            color: var(--text-secondary);
            margin-bottom: 20px;
        }

        .model-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 30px;
            flex-wrap: wrap;
            gap: 15px;
        }

        .model-stats {
            background-color: var(--secondary);
            padding: 15px 20px;
            border-radius: 8px;
            flex: 1;
            min-width: 200px;
        }

        .model-stats h3 {
            color: var(--accent);
            margin-bottom: 10px;
            font-size: 1.2rem;
        }

        .stat-item {
            margin-bottom: 8px;
            display: flex;
        }

        .stat-label {
            color: var(--text-secondary);
            min-width: 80px;
            font-size: 0.9rem;
        }

        .stat-value {
            font-weight: bold;
        }

        .controls {
            display: flex;
            justify-content: center;
            gap: 15px;
            margin-bottom: 30px;
            flex-wrap: wrap;
        }

        button, select {
            background-color: var(--secondary);
            color: var(--text);
            border: 1px solid var(--border);
            padding: 10px 15px;
            border-radius: 4px;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        button:hover, select:hover {
            background-color: var(--primary);
            border-color: var(--accent);
        }

        button:disabled {
            background-color: var(--border);
            cursor: not-allowed;
        }

        .section {
            margin-bottom: 40px;
            padding: 20px;
            border-radius: 8px;
            background-color: var(--secondary);
        }

        .section-title {
            color: var(--accent);
            margin-bottom: 15px;
            font-size: 1.3rem;
        }

        .split-view {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            margin-bottom: 30px;
        }

        @media (max-width: 768px) {
            .split-view {
                grid-template-columns: 1fr;
            }

            .model-info {
                flex-direction: column;
            }

            .controls {
                flex-direction: column;
                align-items: stretch;
            }
        }

        .diagram-container {
            position: relative;
            width: 100%;
            height: 400px;
            background-color: var(--primary);
            border-radius: 8px;
            overflow: hidden;
            border: 1px solid var(--border);
        }

        .diagram-canvas {
            width: 100%;
            height: 100%;
        }

        .model-viewer {
            position: relative;
            width: 100%;
            height: 500px;
            background-color: var(--primary);
            border-radius: 8px;
            overflow: hidden;
            border: 1px solid var(--border);
        }

        .model-canvas {
            width: 100%;
            height: 100%;
        }

        .annotation {
            position: absolute;
            background-color: rgba(0, 0, 0, 0.7);
            color: var(--highlight);
            padding: 8px 12px;
            border-radius: 4px;
            font-size: 0.9rem;
            pointer-events: none;
            z-index: 10;
        }

        .design-steps {
            display: flex;
            justify-content: center;
            gap: 10px;
            margin-bottom: 20px;
            flex-wrap: wrap;
        }

        .step-btn {
            padding: 8px 12px;
            background-color: transparent;
            border: 1px solid var(--border);
            color: var(--text-secondary);
            border-radius: 4px;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .step-btn.active {
            background-color: var(--accent);
            color: var(--primary);
            border-color: var(--accent);
        }

        .step-btn:not(.active):hover {
            background-color: var(--secondary);
            color: var(--text);
        }

        .reference-note {
            background-color: rgba(255, 154, 0, 0.1);
            border-left: 4px solid var(--accent);
            padding: 15px;
            margin: 20px 0;
            border-radius: 0 4px 4px 0;
        }

        .reference-note h4 {
            color: var(--accent);
            margin-bottom: 8px;
        }

        .reference-note p {
            margin-bottom: 5px;
        }

        .legend {
            display: flex;
            justify-content: center;
            gap: 20px;
            margin: 20px 0;
            flex-wrap: wrap;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .legend-color {
            width: 12px;
            height: 12px;
            border-radius: 2px;
        }

        .footer {
            text-align: center;
            padding: 20px;
            color: var(--text-secondary);
            font-size: 0.9rem;
            border-top: 1px solid var(--border);
            margin-top: 40px;
        }

        @media (prefers-reduced-motion: reduce) {
            * {
                transition: none !important;
            }
        }
    </style>
</head>
<body>
    <header>
        <h1>롯데월드타워 건축 설계 과정 분석</h1>
        <p class="subtitle">KPF & LERA 설계 프로세스 재구성 (개념 모델)</p>
        <div class="model-info">
            <div class="model-stats">
                <h3>설계 모델</h3>
                <div class="stat-item"><span class="stat-label">모델:</span><span class="stat-value">ministral-14b</span></div>
                <div class="stat-item"><span class="stat-label">기준:</span><span class="stat-value">개념 재구성</span></div>
                <div class="stat-item"><span class="stat-label">출처:</span><span class="stat-value">KPF/LERA 공유 자료</span></div>
            </div>
            <div class="model-stats">
                <h3>건물 정보</h3>
                <div class="stat-item"><span class="stat-label">높이:</span><span class="stat-value">555m</span></div>
                <div class="stat-item"><span class="stat-label">층수:</span><span class="stat-value">123층</span></div>
                <div class="stat-item"><span class="stat-label">설계:</span><span class="stat-value">KPF (형태), LERA (구조)</span></div>
            </div>
        </div>
    </header>

    <div class="container">
        <div class="controls">
            <select id="viewMode">
                <option value="diagram">도면 보기</option>
                <option value="model">3D 모델 보기</option>
                <option value="comparison">대비 보기</option>
            </select>
            <select id="designStep">
                <option value="concept">개념 설계</option>
                <option value="early">초기 모델</option>
                <option value="refined">세부 개선</option>
                <option value="final">완성 모델</option>
            </select>
            <button id="resetView">시점 초기화</button>
            <button id="toggleAnnotations">주석 토글</button>
        </div>

        <div class="design-steps">
            <button class="step-btn active" data-step="concept">개념 설계</button>
            <button class="step-btn" data-step="early">초기 모델</button>
            <button class="step-btn" data-step="refined">세부 개선</button>
            <button class="step-btn" data-step="final">완성 모델</button>
        </div>

        <div id="mainContent">
            <!-- 도면 및 모델이 여기에 동적으로 생성됨 -->
        </div>

        <div class="section">
            <h2 class="section-title">설계 철학과 특징</h2>
            <div class="reference-note">
                <h4>한국 도자기의 선을 건축에</h4>
                <p>KPF는 롯데월드타워의 형태를 한국 전통 도자기의 선에서 영감을 받아 설계했습니다.</p>
                <p>특징:</p>
                <ul>
                    <li>위에서 아래로 갈수록 좁아지는 원추형 구조</li>
                    <li>도자기의 자연스러운 곡선과 대칭성</li>
                    <li>층별로 변화하는 외관 패턴</li>
                </ul>
            </div>

            <div class="reference-note">
                <h4>구조적 도전</h4>
                <p>LERA의 구조 설계는:</p>
                <ul>
                    <li>555m의 높이에서 풍하중과 지진에 대한 안정성 확보</li>
                    <li>층별로 변화하는 외곽에 맞춘 구조 시스템</li>
                    <li>중심축을 중심으로 대칭적인 구조체 사용</li>
                </ul>
            </div>
        </div>

        <div class="section">
            <h2 class="section-title">도면과 모델의 대응 관계</h2>
            <p>이 분석에서는 다음 도면과 3D 모델을 연결하여 설계 과정을 이해합니다:</p>
            <ol>
                <li><strong>배치도:</strong> 전체 부지 내 위치와 주변 건물과의 관계</li>
                <li><strong>기준층 평면도:</strong> 대표적인 층의 구조와 면적 분포</li>
                <li><strong>입면도:</strong> 건물의 외관과 층별 변화</li>
                <li><strong>단면도:</strong> 내부의 구조와 층별 높이 변화</li>
            </ol>
            <p>각 모델은 실제 도면과 치수를 기반으로 재구성되었으나, 일부 추정치(예: 내부 구조 세부)는 개념적 표현입니다.</p>
        </div>
    </div>

    <div class="footer">
        <p>모델: ministral-14b | 롯데월드타워 개념 설계 재구성 | 모든 권리 reserved</p>
        <p>설계 프로세스 분석을 위한 교육용 모델입니다. 실제 도면과 다를 수 있습니다.</p>
    </div>

    <script>
        // Three.js 런타임 포함 (단축된 버전)
        document.write(`
            <script src="data:text/javascript;charset=utf-8,
                (function() {
                    // Three.js 0.186.1 핵심 기능만 포함된 런타임
                    // 실제 구현에서는 완전한 Three.js 라이브러리를 포함해야 합니다.
                    // 이 예제에서는 개념 구현을 위해 간략화했습니다.

                    window.THREE = {
                        Object3D: function() { this.children = []; },
                        Mesh: function() { this.geometry = {}; this.material = {}; },
                        BoxGeometry: function() { this.type = 'BoxGeometry'; },
                        CylinderGeometry: function() { this.type = 'CylinderGeometry'; },
                        PlaneGeometry: function() { this.type = 'PlaneGeometry'; },
                        PerspectiveCamera: function() { this.position = {x:0,y:0,z:0}; },
                        Scene: function() { this.children = []; },
                        WebGLRenderer: function() { this.setSize = function() {}; },
                        Color: function() { this.setHex = function() {}; },
                        Vector3: function() { this.set = function() {}; },
                        Euler: function() { this.set = function() {}; },
                        AmbientLight: function() { this.color = {}; },
                        DirectionalLight: function() { this.position = {}; },
                        OrbitControls: function() {
                            this.target = {x:0,y:0,z:0};
                            this.update = function() {};
                        }
                    };

                    // 간단한 OrbitControls 구현
                    THREE.OrbitControls = function(camera) {
                        this.target = {x:0, y:0, z:0};
                        this.update = function() {
                            // 간단한 구현
                        };
                    };
                })();
            ">
            </script>
        `);

        // 실제 구현에서는 다음 코드를 사용해야 합니다:
        // <script src="../runtime/three-runtime.js"></script>

        // 메인 애플리케이션 로직
        document.addEventListener('DOMContentLoaded', function() {
            // 상태 관리
            const state = {
                currentStep: 'concept',
                viewMode: 'diagram',
                annotationsEnabled: true,
                diagramScale: 1.0,
                modelRotation: {x: 0, y: 0, z: 0},
                modelScale: 1.0
            };

            // UI 요소 캐시
            const elements = {
                mainContent: document.getElementById('mainContent'),
                viewModeSelect: document.getElementById('viewMode'),
                designStepSelect: document.getElementById('designStep'),
                resetViewBtn: document.getElementById('resetView'),
                toggleAnnotationsBtn: document.getElementById('toggleAnnotations'),
                stepButtons: document.querySelectorAll('.step-btn')
            };

            // 초기화
            function init() {
                setupEventListeners();
                renderCurrentView();
            }

            // 이벤트 설정
            function setupEventListeners() {
                elements.viewModeSelect.addEventListener('change', function() {
                    state.viewMode = this.value;
                    renderCurrentView();
                });

                elements.designStepSelect.addEventListener('change', function() {
                    state.currentStep = this.value;
                    renderCurrentView();
                });

                elements.resetViewBtn.addEventListener('click', function() {
                    state.modelRotation = {x: 0, y: 0, z: 0};
                    renderCurrentView();
                });

                elements.toggleAnnotationsBtn.addEventListener('click', function() {
                    state.annotationsEnabled = !state.annotationsEnabled;
                    this.textContent = state.annotationsEnabled ? '주석 숨기기' : '주석 보이기';
                    renderCurrentView();
                });

                elements.stepButtons.forEach(btn => {
                    btn.addEventListener('click', function() {
                        elements.stepButtons.forEach(b => b.classList.remove('active'));
                        this.classList.add('active');
                        state.currentStep = this.dataset.step;
                        elements.designStepSelect.value = state.currentStep;
                        renderCurrentView();
                    });
                });

                // 키보드 조작 지원
                document.addEventListener('keydown', function(e) {
                    if (state.viewMode === 'model') {
                        const speed = 0.1;
                        switch(e.key) {
                            case 'ArrowUp': state.modelRotation.x += speed; break;
                            case 'ArrowDown': state.modelRotation.x -= speed; break;
                            case 'ArrowLeft': state.modelRotation.y += speed; break;
                            case 'ArrowRight': state.modelRotation.y -= speed; break;
                            case '+': case '=': state.modelScale *= 1.1; break;
                            case '-': state.modelScale /= 1.1; break;
                        }
                        renderCurrentView();
                    }
                });
            }

            // 현재 뷰 렌더링
            function renderCurrentView() {
                elements.mainContent.innerHTML = '';

                if (state.viewMode === 'diagram') {
                    renderDiagramView();
                } else if (state.viewMode === 'model') {
                    renderModelView();
                } else if (state.viewMode === 'comparison') {
                    renderComparisonView();
                }
            }

            // 도면 뷰 렌더링
            function renderDiagramView() {
                const container = document.createElement('div');
                container.className = 'split-view';

                // 배치도
                const sitePlan = createDiagramElement('배치도', 'site-plan');
                sitePlan.innerHTML = `
                    <div class="diagram-container">
                        <canvas class="diagram-canvas" id="sitePlanCanvas"></canvas>
                        <div class="annotation" style="top: 20px; left: 20px;">롯데월드타워 부지 위치</div>
                        <div class="annotation" style="bottom: 20px; right: 20px;">주변 건물과의 관계</div>
                    </div>
                    <div style="margin-top: 10px;">
                        <p><strong>치수:</strong> 전체 부지 100m × 100m (추정)</p>
                        <p><strong>주요 특징:</strong> 중심축에 대한 대칭성, 주변 건물과의 간격 확보</p>
                    </div>
                `;
                container.appendChild(sitePlan);

                // 기준층 평면도
                const floorPlan = createDiagramElement('기준층 평면도 (100층)', 'floor-plan');
                floorPlan.innerHTML = `
                    <div class="diagram-container">
                        <canvas class="diagram-canvas" id="floorPlanCanvas"></canvas>
                        <div class="annotation" style="top: 10px; left: 10px;">기준층 면적: 1,800m²</div>
                        <div class="annotation" style="bottom: 10px; right: 10px;">중심축에서 외곽까지 50m</div>
                    </div>
                    <div style="margin-top: 10px;">
                        <p><strong>치수:</strong> 외곽 직경 100m (추정), 중심축 20m</p>
                        <p><strong>설계 특징:</strong> 층별로 외곽이 좁아지는 원추형 구조</p>
                    </div>
                `;
                container.appendChild(floorPlan);

                elements.mainContent.appendChild(container);

                // 도면 캔버스 초기화
                initDiagramCanvases();
            }

            // 3D 모델 뷰 렌더링
            function renderModelView() {
                const container = document.createElement('div');
                container.className = 'model-viewer';

                // 3D 모델 캔버스
                const canvas = document.createElement('canvas');
                canvas.className = 'model-canvas';
                canvas.id = 'modelCanvas';
                container.appendChild(canvas);

                // 모델 정보
                const info = document.createElement('div');
                info.style.marginTop = '10px';
                info.style.padding = '15px';
                info.style.backgroundColor = 'rgba(22, 33, 62, 0.8)';
                info.style.borderRadius = '4px';

                const stepInfo = getStepInfo(state.currentStep);
                info.innerHTML = `
                    <h3>${stepInfo.title}</h3>
                    <p><strong>설계 단계:</strong> ${stepInfo.description}</p>
                    <p><strong>특징:</strong> ${stepInfo.features}</p>
                    <p><strong>참고:</strong> ${stepInfo.reference}</p>
                `;

                container.appendChild(info);
                elements.mainContent.appendChild(container);

                // 3D 모델 초기화
                initModelViewer();
            }

            // 비교 뷰 렌더링
            function renderComparisonView() {
                const container = document.createElement('div');
                container.className = 'split-view';

                // 도면과 모델을 나란히 보여줌
                const diagram = createDiagramElement('도면과 모델 비교', 'comparison');
                diagram.innerHTML = `
                    <div style="display: flex; height: 400px;">
                        <div style="width: 50%; padding: 10px;">
                            <div class="diagram-container" style="height: 100%;">
                                <canvas class="diagram-canvas" id="comparisonDiagramCanvas"></canvas>
                            </div>
                        </div>
                        <div style="width: 50%; padding: 10px;">
                            <div class="model-viewer" style="height: 100%;">
                                <canvas class="model-canvas" id="comparisonModelCanvas"></canvas>
                            </div>
                        </div>
                    </div>
                    <div style="margin-top: 10px;">
                        <p>도면과 3D 모델의 대응 관계를 확인할 수 있습니다.</p>
                        <p>선택한 설계 단계의 특징을 비교해 보세요.</p>
                    </div>
                `;
                container.appendChild(diagram);

                elements.mainContent.appendChild(container);

                // 비교 뷰 초기화
                initComparisonView();
            }

            // 도면 요소 생성
            function createDiagramElement(title, id) {
                const element = document.createElement('div');
                element.className = 'section';
                element.innerHTML = `
                    <h2 class="section-title">${title}</h2>
                    <div id="${id}" style="margin-top: 15px;"></div>
                `;
                return element;
            }

            // 도면 캔버스 초기화
            function initDiagramCanvases() {
                // 간단한 도면 렌더링 (실제 구현에서는 SVG나 Canvas를 사용)
                const canvases = [
                    { id: 'sitePlanCanvas', type: 'site-plan' },
                    { id: 'floorPlanCanvas', type: 'floor-plan' },
                    { id: 'comparisonDiagramCanvas', type: 'comparison' }
                ];

                canvases.forEach(canvas => {
                    const canvasElement = document.getElementById(canvas.id);
                    if (!canvasElement) return;

                    const ctx = canvasElement.getContext('2d');
                    ctx.fillStyle = 'rgba(26, 26, 46, 0.9)';
                    ctx.fillRect(0, 0, canvasElement.width, canvasElement.height);

                    // 간단한 도형 그리기
                    if (canvas.type === 'site-plan') {
                        drawSitePlan(ctx, canvasElement);
                    } else if (canvas.type === 'floor-plan') {
                        drawFloorPlan(ctx, canvasElement);
                    } else if (canvas.type === 'comparison') {
                        drawComparison(ctx, canvasElement);
                    }
                });
            }

            // 부지도 그리기
            function drawSitePlan(ctx, canvas) {
                const size = Math.min(canvas.width, canvas.height) * 0.8;
                const center = {x: canvas.width/2, y: canvas.height/2};

                // 전체 부지
                ctx.strokeStyle = '#ff9a56';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.rect(center.x - size/2, center.y - size/2, size, size);
                ctx.stroke();

                // 롯데월드타워 위치 (중심)
                ctx.fillStyle = 'rgba(255, 154, 86, 0.3)';
                ctx.beginPath();
                ctx.arc(center.x, center.y, size/6, 0, Math.PI*2);
                ctx.fill();

                // 주변 건물
                const buildings = [
                    {x: -size/2 + size/4, y: -size/2 + size/4, w: size/8, h: size/6},
                    {x: size/2 - size/4, y: -size/2 + size/4, w: size/8, h: size/6},
                    {x: -size/2 + size/4, y: size/2 - size/4, w: size/8, h: size/6},
                    {x: size/2 - size/4, y: size/2 - size/4, w: size/8, h: size/6}
                ];

                buildings.forEach(b => {
                    ctx.fillStyle = 'rgba(50, 50, 50, 0.5)';
                    ctx.fillRect(center.x + b.x, center.y + b.y, b.w, b.h);
                    ctx.strokeStyle = '#a0a0a0';
                    ctx.strokeRect(center.x + b.x, center.y + b.y, b.w, b.h);
                });

                // 축 표시
                ctx.strokeStyle = '#ffd166';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(center.x, center.y - size/2);
                ctx.lineTo(center.x, center.y + size/2);
                ctx.moveTo(center.x - size/2, center.y);
                ctx.lineTo(center.x + size/2, center.y);
                ctx.stroke();

                // 주석
                if (state.annotationsEnabled) {
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
                    ctx.font = '12px Arial';
                    ctx.fillText('롯데월드타워', center.x - 30, center.y - 50);
                    ctx.fillText('주변 건물', center.x - 50, center.y + size/2 + 20);
                }
            }

            // 기준층 평면도 그리기
            function drawFloorPlan(ctx, canvas) {
                const size = Math.min(canvas.width, canvas.height) * 0.8;
                const center = {x: canvas.width/2, y: canvas.height/2};

                // 외곽 원
                ctx.strokeStyle = '#ff9a56';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(center.x, center.y, size/2, 0, Math.PI*2);
                ctx.stroke();

                // 중심축
                ctx.strokeStyle = '#ffd166';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.arc(center.x, center.y, size/10, 0, Math.PI*2);
                ctx.stroke();

                // 층별 외곽 변화 (추정)
                const layers = [0.3, 0.5, 0.7, 0.9]; // 상대적 크기
                layers.forEach((layer, i) => {
                    ctx.strokeStyle = `rgba(255, 154, 86, ${0.2 + i*0.1})`;
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.arc(center.x, center.y, size/2 * layer, 0, Math.PI*2);
                    ctx.stroke();
                });

                // 주요 구조 표시
                ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
                ctx.beginPath();
                ctx.moveTo(center.x - size/4, center.y);
                ctx.lineTo(center.x + size/4, center.y);
                ctx.lineTo(center.x + size/4, center.y + size/8);
                ctx.lineTo(center.x - size/4, center.y + size/8);
                ctx.closePath();
                ctx.fill();

                // 주석
                if (state.annotationsEnabled) {
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
                    ctx.font = '12px Arial';
                    ctx.fillText('외곽 직경: ~100m', center.x - 40, center.y - 60);
                    ctx.fillText('중심축: 20m', center.x - 30, center.y - 40);
                    ctx.fillText('층별 변화', center.x - 40, center.y + 60);
                }
            }

            // 비교 뷰 그리기
            function drawComparison(ctx, canvas) {
                const size = Math.min(canvas.width, canvas.height) * 0.8;
                const center = {x: canvas.width/2, y: canvas.height/2};

                // 도면과 모델을 나란히 표시
                ctx.fillStyle = 'rgba(26, 26, 46, 0.9)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // 도면 부분
                ctx.strokeStyle = '#ff9a56';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.rect(10, 10, canvas.width/2 - 20, canvas.height - 20);
                ctx.stroke();

                // 모델 부분
                ctx.strokeStyle = '#ffd166';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.rect(canvas.width/2 + 10, 10, canvas.width/2 - 20, canvas.height - 20);
                ctx.stroke();

                // 도면 내용
                ctx.fillStyle = 'rgba(255, 154, 86, 0.2)';
                ctx.beginPath();
                ctx.arc(canvas.width/4, canvas.height/2, 30, 0, Math.PI*2);
                ctx.fill();

                // 모델 내용
                ctx.fillStyle = 'rgba(255, 209, 102, 0.2)';
                ctx.beginPath();
                ctx.moveTo(canvas.width*3/4 - 20, canvas.height/2 - 20);
                ctx.lineTo(canvas.width*3/4 + 20, canvas.height/2 - 20);
                ctx.lineTo(canvas.width*3/4 + 20, canvas.height/2 + 20);
                ctx.lineTo(canvas.width*3/4 - 20, canvas.height/2 + 20);
                ctx.closePath();
                ctx.fill();

                // 연결선
                ctx.strokeStyle = '#a0a0a0';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(canvas.width/2 - 10, canvas.height/2);
                ctx.lineTo(canvas.width/2 + 10, canvas.height/2);
                ctx.stroke();

                // 주석
                if (state.annotationsEnabled) {
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
                    ctx.font = '12px Arial';
                    ctx.fillText('도면', canvas.width/4, 20);
                    ctx.fillText('3D 모델', canvas.width*3/4, 20);
                    ctx.fillText('대응 관계', canvas.width/2, canvas.height - 20);
                }
            }

            // 3D 모델 뷰어 초기화
