                if (!canvas) return;

                // 간단한 3D 렌더링 (실제 구현에서는 Three.js 사용)
                const ctx = canvas.getContext('2d');
                ctx.fillStyle = 'rgba(26, 26, 46, 0.9)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // 모델 그리기
                draw3DModel(ctx, canvas, state.currentStep, state.modelRotation, state.modelScale);

                // 주기적 업데이트 (실제 구현에서는 requestAnimationFrame 사용)
                setInterval(() => {
                    draw3DModel(ctx, canvas, state.currentStep, state.modelRotation, state.modelScale);
                }, 16);
            }

